function predict(data, type) {

    if (!data || data.length < 2) {
        return {
            available: false,
            reason: "Not enough historical data"
        };
    }

    // Split the 10-minute window into two halves.
    // Compare earlier average against recent average.

    const midpoint = Math.floor(data.length / 2);

    const earlier = data.slice(0, midpoint);
    const recent = data.slice(midpoint);

    if (earlier.length === 0 || recent.length === 0) {
        return {
            available: false,
            reason: "Not enough historical data"
        };
    }


    const average = arr =>
        arr.reduce((sum, p) => sum + p.value, 0) / arr.length;


    const earlierAvg = average(earlier);
    const recentAvg = average(recent);

    const current = data[data.length - 1].value;

    // Estimated change per 10 minutes
    let change = recentAvg - earlierAvg;


    /*
       Limit unrealistic projections.
       This prevents noisy simulated sensors from
       producing ridiculous future values.
    */

    let maxChange;

    if (type === "temperature") {
        maxChange = 2.0;
    }
    else if (type === "dissolved_oxygen") {
        maxChange = 1.0;
    }
    else {
        maxChange = 0.5;
    }

    change = Math.max(
        -maxChange,
        Math.min(maxChange, change)
    );


    const p10 = current + change;
    const p20 = current + (change * 2);
    const p30 = current + (change * 3);


    let direction = "STABLE";
    let symbol = "â†’";

    let threshold = 0.1;

    if (type === "dissolved_oxygen") {
        threshold = 0.15;
    }


    if (change > threshold) {
        direction = "RISING";
        symbol = "â†‘";
    }
    else if (change < -threshold) {
        direction = "FALLING";
        symbol = "â†“";
    }


    return {
        available: true,

        current: Number(current.toFixed(2)),

        prediction_10m: Number(p10.toFixed(2)),
        prediction_20m: Number(p20.toFixed(2)),
        prediction_30m: Number(p30.toFixed(2)),

        change_10m: Number(change.toFixed(2)),

        direction: direction,
        symbol: symbol,

        samples: data.length
    };
}


