            sensor_id,
            attack_type,
            severity,
            status,
            message,
            operator_action,
            detected_at,
            acknowledged_at,
            resolved_at,
            resolution_note
        )
        VALUES (
            ${sql(incident.id)},
            ${sql(incident.sensor_id)},
            ${sql(incident.attack_type)},
            ${sql(incident.severity)},
            ${sql(incident.status)},
            ${sql(incident.message)},
            ${sql(incident.operator_action)},
            ${numberOrNull(incident.timestamp)},
            ${numberOrNull(incident.acknowledged_at)},
            ${numberOrNull(incident.resolved_at)},
            ${sql(incident.resolution_note)}
        )
        ON CONFLICT(incident_id) DO UPDATE SET
            status = excluded.status,
            acknowledged_at = excluded.acknowledged_at,
            resolved_at = excluded.resolved_at,
            resolution_note = excluded.resolution_note;
    `);
}

if (statements.length === 0) return null;

msg.topic = statements.join("\n");
msg.payload = null;

return msg;

if (!Array.isArray(msg.payload)) {
    node.warn("Invalid restoration payload");
    return null;
}

node.warn(
    "RESTORE: Forwarding " +
    msg.payload.length +
    " incidents to manager"
);

msg.topic = "restore_incident_state";

return msg;

